import type { ComponentStyleVariantConfig } from "@types";
import type { VerticalTabBarProps } from "./vertical-tab-bar.types";
import type { CSSObject } from "@emotion/react";

import * as RadixTabs from "@radix-ui/react-tabs";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { AccordionClasses } from "@components/accordion";
import { LinkButtonClasses } from "@components/link-button";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "VerticalTabBar";

// Generate child element class names for the component, should match available style slots
export const VerticalTabBarClasses = {
  root: "exp-textura_vertical-tab-bar",
  main: "exp-textura_vertical-tab-bar_main",
  list: "exp-textura_vertical-tab-bar_list",
  header: "exp-textura_vertical-tab-bar_header",
  title: "exp-textura_vertical-tab-bar_title",
  panel: "exp-textura_vertical-tab-bar_panel",
  section: "exp-textura_vertical-tab-bar_section",
  sectionHeader: "exp-textura_vertical-tab-bar_section_header",
  sectionHeaderActive: "exp-textura_vertical-tab-bar_section_header_active",
  sectionHeaderAlwaysOpen: "exp-textura_vertical-tab-bar_section_header_always_open",
  sectionTitle: "exp-textura_vertical-tab-bar_section_title",
  sectionIndicator: "exp-textura_vertical-tab-bar_section_indicator",
  sectionContent: "exp-textura_vertical-tab-bar_section_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (): ComponentStyleVariantConfig => ({
  // Can add variants like 'compact', 'bordered', etc. in the future
});

const generateStyles = (props: VerticalTabBarProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<VerticalTabBarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "row",
    height: "100%",
    width: "100%",
    backgroundColor: "unset",
    color: theme.tab.default.color.content.enabled,
    ...theme.typography.body.md,

    [`.${VerticalTabBarClasses.main}`]: {
      position: "relative",
      userSelect: "none",
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[8]),
      paddingBlock: theme.toRem(theme.spacing[24]),
      paddingInline: theme.toRem(theme.spacing[16]),
      alignItems: "stretch",
      width: theme.toRem(240),
      borderRight: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      overflowY: "auto",
      overflowX: "hidden",
      ":dir(rtl)": {
        borderRight: "none",
        paddingRight: 0,
        marginRight: 0,
        borderLeft: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      },
      ...styleSlots?.main,
    },

    [`.${VerticalTabBarClasses.list}`]: {
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[8]),
      paddingBottom: theme.toRem(theme.spacing[16]),
      alignItems: "stretch",
      ...styleSlots?.list,
    },

    [`.${VerticalTabBarClasses.header}`]: {
      ...theme.typography.heading.sm,
      lineHeight: theme.typography.lineHeight[28],
      paddingBottom: theme.toRem(theme.spacing[16]),
      color: theme.color.content.default,
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[16]),
      alignItems: "flex-start",
      [`.${LinkButtonClasses.root}`]: {
        paddingInlineStart: theme.toRem(theme.spacing[8]),
      },
      ...styleSlots?.header,
    },

    [`.${VerticalTabBarClasses.title}`]: {
      paddingInlineStart: theme.toRem(theme.spacing[8]),
      ...styleSlots?.title,
    },

    [`.${VerticalTabBarClasses.panel}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.default,
      cursor: "default",
      flex: 1,
      backgroundClip: "content-box",
      outline: "none",
      borderRadius: theme.toRem(theme.border.radius.sm),
      padding: theme.toRem(theme.spacing[24]),
      "&:focus-visible": {
        ...styleSlots?.panelFocus,
      },
      "&:active": {
        ...styleSlots?.panelActive,
      },
      ...styleSlots?.panel,
    },

    [`.${VerticalTabBarClasses.section}`]: {
      ...styleSlots?.section,
    },

    [`.${AccordionClasses.sm}`]: {
      overflowX: "visible",
      [`.${AccordionClasses.header}`]: {
        borderTop: "none",
      },
      [`.${VerticalTabBarClasses.sectionHeader}`]: {
        display: "flex",
        alignItems: "center",
        width: "100%",
        paddingInlineStart: theme.toRem(theme.spacing[8]),
        paddingBottom: theme.toRem(theme.spacing[4]),
        marginBottom: theme.toRem(theme.spacing[4]),
        backgroundColor: "transparent",
        border: "none",
        cursor: "pointer",
        borderRadius: theme.toRem(theme.border.radius.sm),
        ...theme.typography.label.md,
        color: theme.color.content.default,
        transition: "0.2s background-color ease",
        [`.${AccordionClasses.indicator}`]: {
          width: theme.toRem(12),
        },
        "&[data-expanded=false]": {
          [`&.${VerticalTabBarClasses.sectionHeaderActive}`]: {
            backgroundColor: theme.tab.vertical.color.background.selected,
            color: theme.tab.vertical.color.content.selected,
            ...styleSlots?.sectionHeaderActive,
          },
        },
        ...styleSlots?.sectionHeader,
      },
      [`.${AccordionClasses.contentInner}`]: {
        display: "flex",
        flexDirection: "column",
        gap: theme.toRem(theme.spacing[8]),
        paddingBottom: theme.toRem(theme.spacing[8]),
        padding: theme.toRem(2),
      },
      [`.${AccordionClasses.contentContainer}`]: {
        margin: `calc(${theme.toRem(2)} * -1)`,
      },
    },

    [`.${VerticalTabBarClasses.sectionHeaderAlwaysOpen}`]: {
      [`&.${AccordionClasses.button}`]: {
        cursor: "default",
      },
      ...styleSlots?.sectionHeaderAlwaysOpen,
    },

    [`.${VerticalTabBarClasses.sectionTitle}`]: {
      flex: 1,
      textAlign: "left",
      ...theme.typography.body.smEmphasis,
      ":dir(rtl)": {
        textAlign: "right",
      },
      ...styleSlots?.sectionTitle,
    },

    [`.${VerticalTabBarClasses.sectionIndicator}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.icon,
      fontSize: theme.toRem(16),
      transition: "transform 0.2s ease",
      "&[data-expanded=true]": {
        transform: "rotate(90deg)",
      },
      ":dir(rtl)": {
        transform: "rotate(180deg)",
        "&[data-expanded=true]": {
          transform: "rotate(90deg)",
        },
      },
      ...styleSlots?.sectionIndicator,
    },

    [`.${VerticalTabBarClasses.sectionContent}`]: {
      ":dir(rtl)": {
        paddingLeft: 0,
      },
      ...styleSlots?.sectionContent,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledVerticalTabBar = styled(RadixTabs.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<VerticalTabBarProps>((props) => generateStyles(props));
